-- ============================================================================
-- Table + seed data: State LLC Formation Requirements (FormaCorp)
-- Source: state Secretary of State sites, verified Jan 2026 fee tables
-- ============================================================================

CREATE TABLE IF NOT EXISTS state_formation_requirements (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  state text UNIQUE NOT NULL,
  state_name text NOT NULL,
  llc_filing_fee text,
  annual_report_fee text,
  processing_time text,
  sos_url text,
  notes text,
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE state_formation_requirements ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow read for authenticated" ON state_formation_requirements;
CREATE POLICY "Allow read for authenticated" ON state_formation_requirements
  FOR SELECT USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Allow all for authenticated" ON state_formation_requirements;
CREATE POLICY "Allow all for authenticated" ON state_formation_requirements
  FOR ALL USING (auth.role() = 'authenticated') WITH CHECK (auth.role() = 'authenticated');

